const API = import.meta.env.VITE_API_URL || 'http://localhost:4000/api';
const sampleGeoJSON = { type: 'FeatureCollection', features: [{ type: 'Feature', properties: { name: 'Delhi sample road' }, geometry: { type: 'LineString', coordinates: [[77.20, 28.61], [77.23, 28.63], [77.26, 28.62]] } }] };

async function api(path, options = {}) { const token = localStorage.getItem('geochain_token'); const headers = { ...(options.body instanceof FormData ? {} : { 'Content-Type': 'application/json' }), ...(token ? { Authorization: `Bearer ${token}` } : {}) }; const response = await fetch(`${API}${path}`, { ...options, headers: { ...headers, ...options.headers } }); const data = await response.json(); if (response.status === 401 && token && !path.startsWith('/auth/')) { localStorage.removeItem('geochain_token'); localStorage.removeItem('geochain_user'); window.dispatchEvent(new Event('geochain-auth-expired')); } if (!response.ok) throw new Error(data.error || 'Request failed'); return data; }
function useRouter() { const [path, setPath] = useState(window.location.pathname); useEffect(() => { const onPop = () => setPath(window.location.pathname); window.addEventListener('popstate', onPop); return () => window.removeEventListener('popstate', onPop); }, []); const navigate = to => { window.history.pushState({}, '', to); setPath(to); window.scrollTo(0, 0); }; return { path, navigate }; }
function currentUser() { try { return JSON.parse(localStorage.getItem('geochain_user') || 'null'); } catch { return null; } }
function FitGeoJSON({ data }) { const map = useMap(); useEffect(() => { if (!data) return; try { const layer = new L.GeoJSON(data); const bounds = layer.getBounds(); if (bounds.isValid()) map.fitBounds(bounds, { padding: [24, 24] }); } catch {} }, [data, map]); return null; }

function App() { const { path, navigate } = useRouter(); const [user, setUser] = useState(currentUser()); const [toast, setToast] = useState(''); useEffect(() => { const expire = () => { setUser(null); navigate('/login'); setToast('Your session expired. Please sign in again.'); }; window.addEventListener('geochain-auth-expired', expire); const token = localStorage.getItem('geochain_token'); let timer; if (token) api('/auth/me').then(({ user: freshUser }) => { localStorage.setItem('geochain_user', JSON.stringify(freshUser)); setUser(freshUser); }).catch(() => {}); try { const payload = token ? JSON.parse(atob(token.split('.')[1].replace(/-/g, '+').replace(/_/g, '/'))) : null; if (payload?.exp) timer = setTimeout(expire, Math.max(0, payload.exp * 1000 - Date.now())); } catch {} return () => { window.removeEventListener('geochain-auth-expired', expire); if (timer) clearTimeout(timer); }; }, [navigate]); useEffect(() => { if (user && (path === '/login' || path === '/register')) navigate('/dashboard'); }, [user, path]); const login = result => { localStorage.setItem('geochain_token', result.token); localStorage.setItem('geochain_user', JSON.stringify(result.user)); setUser(result.user); setToast(''); navigate('/dashboard'); }; const logout = () => { localStorage.clear(); setUser(null); navigate('/login'); };
  useEffect(() => { if (!user && path !== '/login' && path !== '/register' && path !== '/pending-approval') navigate('/login'); }, [user, path]);
  const shared = { user, navigate, logout };
  const authRoute = path === '/login' || path === '/register';
  const pendingRoute = path === '/pending-approval';
  let page = !user && !authRoute && !pendingRoute ? <AuthPage mode="login" onAuth={login} navigate={navigate} /> : <HomeModern2 {...shared} />;
  if (path === '/login') page = <AuthPage mode="login" onAuth={login} navigate={navigate} />;
  else if (path === '/register') page = <AuthPage mode="register" onRegistered={role => navigate(role === 'PROVIDER' ? '/pending-approval' : '/login')} navigate={navigate} />;
  else if (path === '/pending-approval') page = <PendingPage navigate={navigate} />;
  else if (path === '/dashboard') page = user ? <DashboardPage3 {...shared} /> : <AuthPage mode="login" onAuth={login} navigate={navigate} />;
  else if (path === '/about') page = user ? <AboutPage2 navigate={navigate} /> : <AuthPage mode="login" onAuth={login} navigate={navigate} />;
  else if (path.startsWith('/datasets/')) page = user ? <DatasetPage4 datasetId={path.split('/')[2]} {...shared} /> : <AuthPage mode="login" onAuth={login} navigate={navigate} />;
  return <><HeaderModern6 {...shared} />{page}{toast && <div className="toast" onClick={() => setToast('')}>{toast}</div>}</>;
}

function HeaderModern2({ user, navigate, logout }) {
  const [profileOpen, setProfileOpen] = useState(false); const [query, setQuery] = useState(new URLSearchParams(window.location.search).get('search') || '');
  const logoutNow = e => { e?.preventDefault(); e?.stopPropagation(); setProfileOpen(false); logout(); };
  const connect = async () => { try { if (!window.ethereum) throw new Error('MetaMask is not installed'); await window.ethereum.request({ method: 'eth_requestAccounts' }); } catch (e) { window.alert(e.message); } };
  const submitSearch = e => { e.preventDefault(); window.location.href = `/?search=${encodeURIComponent(query.trim())}#catalog`; };
  return <header className="modern-header"><button className="modern-brand" onClick={() => navigate('/')}><span className="brand-shield">⬡</span><span><b>GEOCHAIN</b><small>Trusted Geospatial Data</small></span></button><nav><button className="active" onClick={() => navigate('/')}>Explore</button><button onClick={() => document.getElementById('catalog')?.scrollIntoView({ behavior: 'smooth' })}>Datasets</button><button onClick={() => navigate('/about')}>About</button></nav><div className="modern-header-actions"><form className="header-search" onSubmit={submitSearch}><input value={query} onChange={e => setQuery(e.target.value)} placeholder="Search datasets, layers, etc..." /><button aria-label="Search">⌕</button></form>{user ? <div className="profile-wrap"><button className="profile-button modern-profile" onClick={() => setProfileOpen(!profileOpen)}><span className="avatar">{initials(user.name)}</span><span className="profile-label"><b>{user.name}</b><small>{user.role}</small></span><span className="chevron">⌄</span></button>{profileOpen && <div className="profile-menu"><div className="profile-menu-header"><span className="avatar large">{initials(user.name)}</span><div><b>{user.name}</b><small>{user.email}</small></div></div><button onClick={() => { setProfileOpen(false); navigate('/dashboard'); }}>Open dashboard</button><button onClick={() => { setProfileOpen(false); logout(); }}>Log out</button></div>}</div> : <button className="wallet-button" onClick={connect}>▣ &nbsp; Connect Wallet</button>}<button className="theme-button">☼</button></div></header>;
}

