function HomeModern2({ navigate, user }) {
  useEffect(() => { let items = []; const apply = () => { document.querySelectorAll('.modern-dataset-card').forEach(card => { const title = card.querySelector('h3')?.textContent?.trim(); const provider = items.find(d => d.title === title)?.providerName || 'Unknown provider'; const target = card.querySelector('.modern-dataset-status span b'); if (target && target.textContent !== provider) target.textContent = provider; }); }; api('/datasets?limit=50').then(({ items: loaded }) => { items = loaded; apply(); }).catch(() => {}); const observer = new MutationObserver(apply); observer.observe(document.body, { childList: true, subtree: true }); return () => observer.disconnect(); }, []);
  return <><HomeModern navigate={navigate} user={user} /><AdminHeroAction user={user} navigate={navigate} /></>;
}

function AdminHeroAction({ user, navigate }) {
  useEffect(() => { if (user?.role !== 'ADMIN') return undefined; const button = document.querySelector('.modern-secondary'); if (!button) return undefined; const original = button.innerHTML; const approve = () => navigate('/dashboard'); button.innerHTML = 'Approve Providers &nbsp; →'; button.addEventListener('click', approve); return () => { button.removeEventListener('click', approve); button.innerHTML = original; }; }, [user?.role, navigate]);
  return null;
}

function DashboardPage3(props) { return props.user?.role === 'PROVIDER' ? <ProviderDashboard {...props} /> : <DashboardPage2 {...props} />; }

function ProviderDashboard({ navigate }) {
  const [form, setForm] = useState({ title: '', description: '', file: null }); const [error, setError] = useState(''); const [dragging, setDragging] = useState(false);
  const chooseFile = file => { if (file && !file.name.toLowerCase().endsWith('.geojson')) return setError('Please choose a .geojson file'); setForm(current => ({ ...current, file })); setError(''); };
  const upload = async e => { e.preventDefault(); if (!form.file) return setError('Please choose a GeoJSON file'); try { const body = new FormData(); body.append('title', form.title); body.append('description', form.description); body.append('file', form.file); const created = await api('/datasets', { method: 'POST', body }); navigate(`/datasets/${created.datasetId}`); } catch (x) { setError(x.message); } };
  return <main className="provider-dashboard"><section className="provider-hero"><div><p className="eyebrow">PROVIDER WORKSPACE</p><h1>Publish <em>trusted</em> data.</h1><p>Upload a GeoJSON layer, inspect its fingerprint,<br />and register its provenance on the blockchain.</p></div><div className="provider-hero-art"><span>⌁</span><i>◇</i><b>♧</b></div></section><div className="provider-dashboard-grid"><section className="provider-upload-card"><div className="provider-card-heading"><span>♧</span><div><h2>Upload a dataset</h2><p>Fill in the details below and upload your GeoJSON file.</p></div></div><form onSubmit={upload}><label>♧ &nbsp; Title *<input required value={form.title} onChange={e => setForm({ ...form, title: e.target.value })} placeholder="Enter a descriptive title for your dataset" /></label><label>▧ &nbsp; Description *<textarea required value={form.description} onChange={e => setForm({ ...form, description: e.target.value })} placeholder="Describe your dataset, its source, purpose, and any relevant details..." /></label><label>♧ &nbsp; GeoJSON File *<div className={`geojson-dropzone ${dragging ? 'dragging' : ''}`} onDragOver={e => { e.preventDefault(); setDragging(true); }} onDragLeave={() => setDragging(false)} onDrop={e => { e.preventDefault(); setDragging(false); chooseFile(e.dataTransfer.files[0]); }}><span className="upload-cloud">♧</span><b>Drag and drop your GeoJSON file here</b><small>or</small><button type="button" onClick={() => document.getElementById('provider-file').click()}>Choose File</button><span>{form.file?.name || 'No file chosen'}</span><input id="provider-file" type="file" accept=".geojson,application/geo+json" onChange={e => chooseFile(e.target.files[0])} /></div><small className="file-help">♧ Only .geojson or .json files are supported. Maximum file size: 20MB</small></label><button className="provider-submit">♧ &nbsp; Validate and Upload Dataset &nbsp; →</button>{error && <p className="form-error">{error}</p>}</form></section><aside className="provider-next-card"><h2>What happens next?</h2>{[['♧','Validate & Inspect','We validate your GeoJSON and extract its metadata.'],['♧','Generate Fingerprint','A SHA-256 hash (fingerprint) is generated for integrity.'],['♧','Store & Register','File is stored off-chain and metadata is saved in our database.'],['♧','Register on Blockchain','You can register the dataset hash on-chain using MetaMask.'],['♧','Provenance Guaranteed','Your dataset gets a tamper-proof provenance record.']].map(([icon,title,text]) => <div className="provider-step" key={title}><span>{icon}</span><div><b>{title}</b><p>{text}</p></div></div>)}<div className="provider-note">▢ &nbsp; <span><b>Your data. Your ownership.</b><small>We ensure transparency and trust.</small></span></div></aside></div></main>;
}

function DatasetPage4({ datasetId, user, navigate }) {
  const [dataset, setDataset] = useState(null); const [geojson, setGeojson] = useState(null); const [message, setMessage] = useState(''); const [result, setResult] = useState(null);
  useEffect(() => { let cancelled = false; api(`/datasets/${datasetId}`).then(async d => { const response = await fetch(`${API}/datasets/${datasetId}/download`); if (!response.ok) throw new Error('Unable to load the dataset file'); const file = await response.json(); if (!cancelled) { setDataset(d); setGeojson(file); } }).catch(e => { if (!cancelled) setMessage(e.message); }); return () => { cancelled = true; }; }, [datasetId]);
  useEffect(() => { if (message && /ACTION_REJECTED|user rejected|user denied|ethers-user-denied/i.test(message)) setMessage('Registration cancelled in MetaMask. The dataset is still pending.'); }, [message]);
  if (!dataset) return <main className="status-page"><p>{message || 'Loading dataset…'}</p></main>;
  const pending = dataset.status !== 'VERIFIED'; const version = dataset.versions?.[dataset.versions.length - 1] || {}; const date = value => value ? new Date(value).toLocaleString([], { dateStyle: 'medium', timeStyle: 'short' }) : '—';
  const remove = async () => { if (!window.confirm('Delete this pending dataset permanently?')) return; try { await api(`/datasets/${datasetId}`, { method: 'DELETE' }); navigate('/dashboard'); } catch (e) { setMessage(e.message); } };
  const verify = async e => { if (pending) return; const body = new FormData(); body.append('file', e.target.files[0]); try { setResult(await api(`/datasets/${datasetId}/verify`, { method: 'POST', body })); } catch (x) { setMessage(x.message); } };
  const register = async () => { try { if (!window.ethereum) throw new Error('MetaMask is not installed'); const cfg = await api('/blockchain/config'); if (!cfg.enabled) throw new Error('Blockchain RPC and contract address are not configured'); const provider = new BrowserProvider(window.ethereum); const network = await provider.getNetwork(); if (cfg.network === 'sepolia' && network.chainId !== 11155111n) throw new Error('Switch MetaMask to Sepolia'); const signer = await provider.getSigner(); const contract = new Contract(cfg.contractAddress, ['function registerDataset(bytes32,bytes32,string) external'], signer); const tx = await contract.registerDataset(id(dataset.datasetId), `0x${dataset.sha256}`, dataset.ipfsCid || ''); setMessage(`Transaction submitted: ${tx.hash}`); await tx.wait(); await api(`/datasets/${datasetId}/blockchain-confirm`, { method: 'POST', body: JSON.stringify({ transactionHash: tx.hash, ipfsCid: dataset.ipfsCid || null }) }); setDataset({ ...dataset, status: 'VERIFIED', versions: [...(dataset.versions || []).slice(0, -1), { ...version, transactionHash: tx.hash }] }); setMessage('Dataset verified on-chain'); } catch (e) { setMessage(e.message); } };
  return <main className="dataset-modern"><button className="dataset-back" onClick={() => navigate('/')}>← Back to catalog</button><section className="dataset-modern-hero"><div><p className="eyebrow">DATASET DETAIL</p><h1>{dataset.title}</h1><p>{dataset.description || 'No description provided.'}</p></div><div className="dataset-hero-cards"><span><b>{dataset.status === 'VERIFIED' ? '✓ VERIFIED' : dataset.status}</b><small>{dataset.status === 'VERIFIED' ? 'On Blockchain' : 'Awaiting registration'}</small></span><span><b>▱ v{version.version || 1}</b><small>Version</small></span><span><b>▣ {date(dataset.updatedAt).split(',')[0]}</b><small>Updated</small></span><span><b>♙ {dataset.providerName || 'Unknown provider'}</b><small>Owner</small></span></div></section><div className="dataset-modern-grid"><section className="dataset-preview-card"><h2>▧ &nbsp; Dataset Preview</h2><div className="dataset-modern-map"><DatasetMap data={geojson} datasetId={datasetId} /></div></section><section className="dataset-metadata-card"><h2>▤ &nbsp; Metadata</h2><div className="dataset-facts"><span>♙ <b>Features</b><strong>{dataset.metadata?.featureCount ?? '—'}</strong></span><span>♧ <b>Geometry</b><strong>{dataset.metadata?.geometryTypes?.join(', ') || '—'}</strong></span><span>◇ <b>CRS</b><strong>{dataset.metadata?.crs || '—'}</strong></span><span>▣ <b>File size</b><strong>{dataset.metadata?.fileSize ? `${dataset.metadata.fileSize} bytes` : '—'}</strong></span><span>▧ <b>SHA-256 Hash</b><strong>{dataset.sha256 || '—'}</strong></span><span>♧ <b>IPFS CID</b><strong>{dataset.ipfsCid || 'Not pinned'}</strong></span><span>◷ <b>Registered on</b><strong>{date(dataset.createdAt)}</strong></span><span>◷ <b>Updated on</b><strong>{date(dataset.updatedAt)}</strong></span></div><div className="dataset-modern-actions"><a href={`${API}/datasets/${datasetId}/download`}>⇩ &nbsp; Download Source</a>{pending ? <>{user?.role === 'PROVIDER' && dataset.providerId === user.id && <button onClick={register}>♧ &nbsp; Register with MetaMask</button>}{user?.role === 'PROVIDER' && dataset.providerId === user.id && <button className="delete-modern" onClick={remove}>Delete pending dataset</button>}</> : <label>♧ &nbsp; Verify Registered File<input type="file" accept=".geojson,application/geo+json" onChange={verify} /></label>}</div>{message && <p className="form-message">{message}</p>}{result && <p className={result.valid ? 'verify-result valid' : 'verify-result invalid'}>{result.valid ? '✓ DATASET VERIFIED' : '✕ VERIFICATION FAILED'}</p>}</section></div><section className="dataset-integrity"><span>✓</span><div><b>Data Integrity Guaranteed</b><p>{pending ? 'This dataset is awaiting blockchain registration.' : 'This dataset is registered on the blockchain. Any modification to the file will change its fingerprint and fail verification.'}</p></div><small>Blockchain Tx Hash<br /><b>{version.transactionHash || 'Pending registration'}</b></small><small>Network<br /><b>Sepolia Testnet</b></small></section></main>;
}

